export function getEffectiveMeshDensity(config: EnemyConfig): MeshDensity {
  return config.morphology.meshDensity ?? 'medium';
}

export function getEffectiveTexturePattern(config: EnemyConfig): TexturePatternId {
  if (config.materials.texturePattern) {
    return config.materials.texturePattern;
  }
  if (FURRY_BEAST_ARCHETYPES.has(config.archetype)) {
    return 'wolf_fur';
  }
  if (
    config.raceCategory === 'dragons' ||
    config.bodyPlan === 'dragon_wyvern' ||
    config.bodyPlan === 'serpentine_naga' ||
    config.archetype === 'venom_marsh_toad' ||
    config.archetype === 'swamp_poison_newt' ||
    config.archetype === 'horned_field_viper' ||
    config.archetype === 'marsh_leech_worm' ||
    config.archetype === 'young_green_drake' ||
    config.archetype === 'elite_spitting_salamander_drake' ||
    config.archetype === 'elite_casqued_chameleon_stalker' ||
    config.archetype === 'elite_frilled_venom_basilisk' ||
    config.archetype === 'elite_thorny_devil_moloch' ||
    config.archetype === 'elite_hooded_king_cobra' ||
    config.archetype === 'elite_snapping_chelonian_tortoise' ||
    config.archetype === 'elite_swamp_alligator_snapper' ||
    config.archetype === 'elite_abyssal_angler_lurker' ||
    config.archetype === 'elite_crest_pterosaur_skydrake' ||
    config.archetype === 'elite_komodo_monitor_ravager' ||
    config.archetype === 'elite_glacial_plesio_drake' ||
    config.archetype === 'elite_clubtail_ankylo_drake' ||
    config.archetype === 'elite_twin_head_amphisbaena' ||
    config.archetype === 'elite_crimson_wyvern_matriarch' ||
    config.archetype === 'elite_salamander_magma_spearman' ||
    config.archetype === 'wow_murloc_tidehunter' ||
    config.archetype === 'wow_deathwing_cataclysm_aspect' ||
    config.archetype === 'wow_lady_vashj_coilfang_matron' ||
    config.archetype === 'wow_naga_myrmidon_royal_guard' ||
    config.archetype === 'wow_hakkar_soulflayer_loa' ||
    config.archetype === 'wow_chromaggus_chromatic_drake' ||
    config.archetype === 'wow_devilsaur_king_mosh' ||
    config.archetype === 'wow_kodo_ancient_warbeast' ||
    config.archetype === 'archer_species_8_lizardfolk_scale_sniper' ||
    config.archetype === 'archer_species_11_naga_siren_coralbow' ||
    config.materials.preset === 'dragon_crimson_scales'
  ) {
    return 'scales';
  }
  if (
    config.bodyPlan === 'arachnid_scorpion' ||
    config.archetype === 'forest_hunter_spider' ||
    config.archetype === 'mud_shell_crab_beetle' ||
    config.archetype === 'dune_yellow_scorpion' ||
    config.archetype === 'briar_wood_spriggan' ||
    config.archetype === 'chitin_stalker' ||
    config.archetype === 'brood_spider_queen' ||
    config.archetype === 'frost_crystal_scorpion' ||
    config.archetype === 'catacomb_necro_arachnid' ||
    config.archetype === 'elite_fungal_myconid_colossus' ||
    config.archetype === 'wow_anubarak_crypt_lord' ||
    config.archetype === 'wow_qiraji_prophet_skeram' ||
    config.archetype === 'wow_silithid_colossus_reaver' ||
    config.archetype === 'archer_species_12_mantid_amber_wingbow'
  ) {
    return 'chitin_fur';
  }
  if (
    config.raceCategory === 'starter_animals' ||
    config.raceCategory === 'beasts' ||
    config.bodyPlan === 'quadruped_beast' ||
    config.materials.preset === 'feral_fur_hide'
  ) {
    return 'wolf_fur';
  }
  if (
    config.raceCategory === 'magical' ||
    config.materials.preset === 'abyssal_obsidian' ||
    config.materials.preset === 'arcane_crystal'
  ) {
    return 'runic_obsidian';
  }
  return 'damascus_plate';
}

export function getEffectiveHairStyle(config: EnemyConfig): Exclude<HairStyleId, 'auto'> {
  if (config.morphology.hairStyle && config.morphology.hairStyle !== 'auto') {
    return config.morphology.hairStyle;
  }
  if (
    config.archetype === 'manticore_chimera' ||
    config.archetype === 'labyrinth_minotaur' ||
    config.archetype === 'cerberus_hellhound' ||
    config.archetype === 'dire_wolf' ||
    config.archetype === 'sabertooth_tiger' ||
    config.archetype === 'astral_centaur' ||
    config.archetype === 'permafrost_warg_alpha' ||
    config.archetype === 'gale_wind_manticore' ||
    config.archetype === 'aurora_ice_centaur' ||
    config.archetype === 'crypt_cerberus_hound' ||
    config.archetype === 'stitched_necromancy_chimera' ||
    config.archetype === 'steppe_spotted_hyena' ||
    config.archetype === 'mountain_bighorn_ram' ||
    config.archetype === 'elite_bloodmane_mandrill' ||
    config.archetype === 'elite_thunderhoof_bison' ||
    config.archetype === 'elite_shadow_maned_lion' ||
    config.archetype === 'elite_satyr_bloodhorn_shaman' ||
    config.archetype === 'elite_centaur_steppe_khan' ||
    config.archetype === 'wow_hogger_gnoll_chieftain' ||
    config.archetype === 'wow_centaur_kolkar_marauder' ||
    config.archetype === 'wow_tauren_cairne_chieftain' ||
    config.archetype === 'wow_worgen_gilneas_stalker' ||
    config.archetype === 'wow_Frostsaber_winterspring_alpha' ||
    config.archetype === 'wow_magnataur_northrend_behemoth'
  ) {
    return 'wild_mane_fur';
  }
  if (
    config.archetype === 'rabid_razorback_boar' ||
    config.archetype === 'iron_boar_juggernaut' ||
    config.archetype === 'phantom_armored_boar' ||
    config.archetype === 'thicket_razor_badger' ||
    config.archetype === 'elite_quillback_porcupine' ||
    config.archetype === 'elite_steppe_dire_jackal' ||
    config.archetype === 'elite_goblin_wolf_rider_boss' ||
    config.archetype === 'elite_bog_troll_regenerator' ||
    config.archetype === 'wow_quillboar_thornweaver' ||
    config.archetype === 'wow_troll_gurubashi_berserker' ||
    config.archetype === 'wow_murloc_tidehunter'
  ) {
    return 'dorsal_mohawk';
  }
  if (FURRY_BEAST_ARCHETYPES.has(config.archetype) || getEffectiveTexturePattern(config) === 'wolf_fur') {
    return 'full_fur_coat';
  }
  if (
    config.archetype === 'vampire_lord' ||
    config.archetype === 'solar_valkyrie' ||
    config.archetype === 'tidal_naiad_queen' ||
    config.archetype === 'valkyrie_of_the_gale' ||
    config.archetype === 'crimson_nosferatu_elder' ||
    config.archetype === 'grave_fallen_valkyrie' ||
    config.archetype === 'banshee_frozen_throne' ||
    config.archetype === 'elite_woolly_mammoth_calf' ||
    config.archetype === 'elite_harpy_storm_matriarch' ||
    config.archetype === 'wow_arthas_lich_king' ||
    config.archetype === 'wow_blood_elf_spellbreaker' ||
    config.archetype === 'wow_night_elf_warden_avatar' ||
    config.archetype === 'wow_valkyr_shadowguard' ||
    config.archetype === 'wow_banshee_dark_ranger_queen' ||
    config.archetype === 'wow_illidan_betrayer_demonhunter'
  ) {
    return 'long_flowing_hair';
  }
  if ((config.morphology.furDensity ?? 0) > 0.08) {
    return 'full_fur_coat';
  }
  return 'none';
}

export function getEffectiveFurDensity(config: EnemyConfig): number {
  if (typeof config.morphology.furDensity === 'number' && Number.isFinite(config.morphology.furDensity)) {
    return config.morphology.furDensity;
  }
  const style = getEffectiveHairStyle(config);
  if (style === 'wild_mane_fur') {
    return 1.25;
  }
  if (style === 'full_fur_coat' || style === 'dorsal_mohawk') {
    return 1.15;
  }
  if (style === 'long_flowing_hair') {
    return 1.0;
  }
  return 0.0;
}

export function getEffectiveHairLength(config: EnemyConfig): number {
  if (typeof config.morphology.hairLength === 'number' && Number.isFinite(config.morphology.hairLength)) {
    return config.morphology.hairLength;
  }
  const style = getEffectiveHairStyle(config);
  if (style === 'wild_mane_fur' || style === 'long_flowing_hair') {
    return 1.2;
  }
  return 1.0;
}

export function getEffectiveMuscleDefinition(config: EnemyConfig): number {
  if (
    typeof config.morphology.muscleDefinition === 'number' &&
    Number.isFinite(config.morphology.muscleDefinition)
  ) {
    return config.morphology.muscleDefinition;
  }
  if (
    config.raceCategory === 'starter_animals' ||
    config.raceCategory === 'low_level' ||
    config.raceCategory === 'beasts' ||
    config.raceCategory === 'dragons' ||
    config.raceCategory === 'mythological'
  ) {
    return 1.18;
  }
  if (config.bodyPlan === 'floating_magical') {
    return 0.45;
  }
  return 0.85;
}

